'use strict';
const TransportRoutes={
 routes:[
  {id:'viking-1959',recordType:'shipRoute',name:'Viking · Gräddö–Mariehamn–Galtby',from:1959,to:1959,dateLabel:'1959 års rutt',color:'#356d88',text:'Bilarna kan följa med över havet. Den 1 juni 1959 börjar Viking trafikera Gräddö, Mariehamn och Galtby.',dateNote:'Den här sträckningen visas för 1959. År 1960 flyttades den svenska anlöpshamnen från Gräddö till Kapellskär. Det är rutten via Gräddö som upphör, inte färjetrafiken.',ports:[{name:'Gräddö',lon:19.04,lat:59.77},{name:'Mariehamn',lon:19.927,lat:60.089},{name:'Galtby',lon:21.59,lat:60.135}],path:[[19.04,59.77],[19.2,59.84],[19.7,59.95],[19.9,60.02],[19.927,60.089],[19.9,60.02],[20.03,59.96],[20.4,59.99],[20.9,60.07],[21.3,60.1],[21.59,60.135]],sources:[['Viking Line · färjetrafikens historia','https://www.vikingline.com/et/kontsern/ajalugu/farjetrafik/'],['Museiverket · bilfärjan 1959','https://www.finna.fi/Record/museovirasto.985d38d2-8b39-42e1-91ca-bfe821219852']]},
  {id:'eckero-1961',recordType:'shipRoute',name:'Eckerö Linjen · Grisslehamn–Eckerö',from:1961,to:2026,dateLabel:'1961–idag',color:'#287e83',text:'Färjan binder ihop Grisslehamn i Sverige med Berghamn på Eckerö. Passagerare, bilar och gods reser över Ålands hav.',dateNote:'Eckerö Linjens trafik startade 1961. Samma hamnförbindelse trafikeras 2026. Linjen visar förbindelsens period, inte ett visst fartyg eller oavbruten daglig trafik.',ports:[{name:'Grisslehamn',lon:18.813516,lat:60.09955},{name:'Berghamn · Eckerö',lon:19.536363,lat:60.225366}],path:[[18.813516,60.09955],[18.9,60.12],[19.12,60.16],[19.4,60.21],[19.536363,60.225366]],sources:[['Mariehamns stads historia · Eckerölinjen sedan 1961','https://bibliotek.mariehamn.ax/fulltext/MariehamnsHistoria_1961-1986.pdf?dl=0'],['Eckerö Linjen · dagens hamnar och förbindelse','https://www.eckerolinjen.se/kontaktuppgifter']]},
  {id:'viking-turku-2026',recordType:'shipRoute',name:'Stockholm–Mariehamn–Åbo',from:2026,to:2026,dateLabel:'Nutida rutt · belagd 2026',color:'#51659a',text:'Stora färjor knyter ihop Stockholm, Mariehamn och Åbo. Åland är en plats där resenärer både stiger av och fortsätter vidare.',dateNote:'Detta är ett urval av Viking Lines förbindelser 2026, inte ruttens startår. Åbolinjen anlöper Mariehamn eller Långnäs; här visas varianten via Mariehamn. Äldre sträckningar är inte daterade i detta lager.',ports:[{name:'Stockholm',lon:18.116,lat:59.315},{name:'Mariehamn',lon:19.927,lat:60.089},{name:'Åbo',lon:22.22,lat:60.435}],path:[[18.116,59.315],[18.4,59.4],[18.8,59.7],[19.4,59.9],[19.9,60.02],[19.927,60.089],[19.9,60.02],[20.03,59.96],[20.4,59.99],[20.9,60.07],[21.3,60.16],[21.7,60.28],[22,60.36],[22.22,60.435]],sources:[['Viking Line · nuvarande förbindelser','https://www.vikingline.com/the-group/viking-line/services/']]}
 ],
 visible(route,year,enabled=true){return enabled&&year>=route.from&&year<=route.to},
 active(year,enabled=true){return this.routes.filter(r=>this.visible(r,year,enabled))},
 draw(ctx,view,screen,enabled,selected){
  const hits=[],ports=new Map();ctx.save();
  for(const route of this.active(view.year,enabled)){
   const path=route.path.map(p=>screen(...p));ctx.strokeStyle=route.color;ctx.lineWidth=route.id===selected?4:2.5;ctx.setLineDash([8,6]);ctx.beginPath();path.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();
   hits.push({route,path});for(const p of route.ports)ports.set(p.name,p);
  }
  ctx.setLineDash([]);ctx.font='11px sans-serif';ctx.textAlign='center';
  for(const p of ports.values()){const[x,y]=screen(p.lon,p.lat);if(x<0||y<0||x>view.width||y>view.height)continue;ctx.fillStyle='#f8f7f1';ctx.strokeStyle='#315b70';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.lineWidth=3;ctx.strokeStyle='#faf7e8';ctx.strokeText(p.name,x,y-10);ctx.fillStyle='#315b70';ctx.fillText(p.name,x,y-10)}ctx.restore();return hits;
 },
 hit(hits,x,y){let best=null,distance=9;for(const h of hits)for(let i=1;i<h.path.length;i++){const a=h.path[i-1],b=h.path[i],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1))),d=Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy);if(d<distance){distance=d;best=h.route}}return best},
 story(route){return `<button class="back" id="backFeature">← Till tidsperioden</button><br><span class="storytag">Fartygsrutt</span><h2>${htmlEscape(route.name)}</h2><p>${htmlEscape(route.text)}</p><div class="dating"><strong>${htmlEscape(route.dateLabel)}</strong><p>${htmlEscape(route.dateNote)}</p></div><p class="asidehint">Streckad linje: schematisk hamnförbindelse. Mellanpunkterna är ritade för överblick, inte uppmätta farleder eller fartygets exakta färdväg.</p><div class="question"><strong>Fundera tillsammans</strong>Vad kan en färja ta med som inte fick plats i en liten postbåt?</div><details><summary>Källor till rutten</summary>${route.sources.map(([name,url])=>`<p><a href="${safeURL(url)}" target="_blank" rel="noopener noreferrer">${htmlEscape(name)} ↗</a></p>`).join('')}</details>`}
};
